-- Phase C — registry load.  GENERATED by scripts/phase_c/gen_registry_load.mjs; do not edit by hand.
--
-- Every row below comes from either the checksum-verified package under docs/phase-c/package/
-- or from a measurement written into docs/phase-c/*.csv by scripts/phase_c/build_*.mjs.  The
-- eight package errata recorded in phase_c_01 are APPLIED here: the prose cells in the
-- authority matrix are stored as the role-id lists they were meant to be, and the placeholder
-- owner of routine_operational_decision is stored as an explicit DYNAMIC scope rather than as
-- an invented role.
--
-- Nothing here activates anything.  No cron row is created or its activation changed, no
-- provider route is opened, no business record is written.
--
-- scripts/sql is append-only.  To change any of this, add a new file.

set lock_timeout = '8s';
set statement_timeout = '600s';


-- 10 system actors.  Each executes; none owns.
insert into public.phase_c_system_actor
  (system_actor_id, description, accountable_role_id, department_id, allowed_actions, forbidden_actions, trace_policy_id) values
  ('system.scheduler', 'Initiates scheduled work. Never the accountable business owner.', 'coo', 'people_company_operations', 'start registered cron/executor bindings only', 'invent owner; bypass authority; change workflow policy', 'TRACE-SYSTEM-EXECUTION'),
  ('system.event_dispatcher', 'Delivers canonical events from the outbox.', 'it_operations_site_reliability_engineer', 'assurance_security_reliability', 'deliver registered event subscriptions', 'create business decisions; alter payload', 'TRACE-SYSTEM-EXECUTION'),
  ('system.webhook_receiver', 'Authenticates and records external webhooks before business handling.', 'backend_engineer', 'product_engineering_ai', 'verify, dedupe and enqueue valid webhook', 'make unclassified business decision', 'TRACE-SYSTEM-EXECUTION'),
  ('system.storage_trigger', 'Executes deterministic storage validation and metadata actions.', 'it_operations_site_reliability_engineer', 'assurance_security_reliability', 'validated registered storage actions', 'expose files or bypass ownership', 'TRACE-SYSTEM-EXECUTION'),
  ('system.health_monitor', 'Runs monitoring and health probes.', 'it_operations_site_reliability_engineer', 'assurance_security_reliability', 'read health and open incident/task', 'silently mutate business state', 'TRACE-MONITORING'),
  ('system.workflow_engine', 'Coordinates canonical workflow/step state.', 'coo', 'people_company_operations', 'state transitions allowed by Phase B', 'override owner, gate or founder boundary', 'TRACE-WORKFLOW'),
  ('system.task_engine', 'Creates, assigns, updates and closes canonical tasks.', 'chief_of_staff', 'exec', 'task lifecycle under registered workflow/command', 'assign unresolved/inactive identity', 'TRACE-TASK'),
  ('system.command_router', 'Deterministically maps founder commands to existing workflow/role targets in zero-cost mode.', 'chief_of_staff', 'exec', 'classify supported command or ask clarification', 'execute raw text directly; guess low-confidence route', 'TRACE-FOUNDER-COMMAND'),
  ('system.notification_dispatcher', 'Delivers approved notification/outbox records.', 'lifecycle_channel_operations_specialist', 'customer_experience_communications', 'send only approved, consent-compliant messages', 'author business message or bypass suppression', 'TRACE-SYSTEM-EXECUTION'),
  ('system.provider_adapter', 'Boundary for external tools/providers. Paid AI remains disabled in Phase C.', 'solution_architect', 'product_engineering_ai', 'registered adapter calls under tool policy', 'unregistered provider, secret fallback or paid inference in Phase C', 'TRACE-TOOL')
on conflict (system_actor_id) do update set
  description = excluded.description, accountable_role_id = excluded.accountable_role_id,
  department_id = excluded.department_id, allowed_actions = excluded.allowed_actions,
  forbidden_actions = excluded.forbidden_actions, trace_policy_id = excluded.trace_policy_id;

-- 11 trace policies.
insert into public.phase_c_trace_policy
  (trace_policy_id, scope, trace_required, minimum_fields, completed_without_trace_allowed) values
  ('TRACE-FOUNDER-COMMAND', 'Every founder command/message that becomes or changes work.', 'YES', 'command_id; message_id; founder_identity; raw_text_hash; interpretation; workflow_ids; task_ids; chief_of_staff_role; status; timestamps', 'NO'),
  ('TRACE-WORKFLOW', 'Every workflow run and workflow state transition.', 'YES', 'workflow_run_id; workflow_id; business_object_id; owner; state_before; state_after; evidence; event_ids; timestamps', 'NO'),
  ('TRACE-STEP', 'Every required workflow step execution or verdict.', 'YES', 'step_run_id; step_id; owner; inputs; output_hash; gates; authority; reviewer; status; timestamps', 'NO'),
  ('TRACE-TASK', 'Every command, workflow or management task lifecycle.', 'YES', 'task_id; source; owner; manager; objective; acceptance; closure; status; timestamps', 'NO'),
  ('TRACE-HANDOFF', 'Every owner-to-owner handoff.', 'YES', 'handoff_run_id; sender; receiver; packet_hash; accept/reject; return_owner; sla; timestamps', 'NO'),
  ('TRACE-CONSEQUENTIAL-DECISION', 'External, financial, privacy, legal, supplier/customer, production or policy-impacting decisions.', 'YES', 'decision_trace_id; role; evidence; assumptions; authority; reviewer; outcome; expected_effect; status', 'NO'),
  ('TRACE-ROLE-ACTION', 'Non-consequential role work that changes company state or creates an official output.', 'YES', 'role; task; evidence_refs; output_hash; status; timestamps', 'NO'),
  ('TRACE-CATEGORY-ADVICE', 'Every category-overlay invocation.', 'YES', 'overlay_id; inquiry_id; route; retrieved_fields; never_infer_checks; missing_fields; return_owner; status', 'NO'),
  ('TRACE-TOOL', 'Every external/internal tool invocation.', 'YES', 'tool_call_id; tool_id; caller_role; request_hash; result_hash/error; permission; latency; status', 'NO'),
  ('TRACE-SYSTEM-EXECUTION', 'Scheduled, webhook, queue, storage and provider-adapter execution that may mutate or deliver state.', 'YES', 'execution_id; system_actor; accountable_role; component_id; input_hash; output_hash; status; timestamps', 'NO'),
  ('TRACE-MONITORING', 'Read-only health probes.', 'COMPACT', 'probe_id; component_id; status; anomaly; incident_or_task_id; timestamps', 'YES_WHEN_HEALTHY_AND_AGGREGATED')
on conflict (trace_policy_id) do update set
  scope = excluded.scope, trace_required = excluded.trace_required,
  minimum_fields = excluded.minimum_fields,
  completed_without_trace_allowed = excluded.completed_without_trace_allowed;

