-- command and task state models

insert into public.phase_c_command_state (state, definition, terminal) values
  ('received', 'Raw founder message recorded; no work yet.', false),
  ('interpreting', 'Deterministic registry/parser evaluating scope.', false),
  ('clarification_required', 'Command cannot be safely routed without one clarification.', false),
  ('accepted', 'Interpretation accepted and plan ready.', false),
  ('routed', 'Exact workflow/role plan resolved.', false),
  ('tasks_created', 'All immediate tasks created atomically.', false),
  ('in_progress', 'At least one child task executing.', false),
  ('partially_blocked', 'One or more child tasks blocked; command owner still active.', false),
  ('completed', 'All required child tasks closed and completion summary delivered.', true),
  ('cancelled', 'Founder or permitted workflow cancellation completed.', true),
  ('refused', 'Unsafe, forbidden or unsupported command refused with reason.', true),
  ('superseded', 'Replaced by a newer founder command.', true),
  ('failed', 'System failure prevented safe routing/execution; incident/task created.', true)
on conflict (state) do update set definition = excluded.definition, terminal = excluded.terminal;

insert into public.phase_c_command_transition (from_state, to_state, condition) values
  ('received', 'interpreting', 'command intake accepted'),
  ('interpreting', 'clarification_required', 'low confidence/required parameter missing'),
  ('clarification_required', 'interpreting', 'founder clarification received'),
  ('interpreting', 'accepted', 'safe interpretation complete'),
  ('interpreting', 'refused', 'forbidden/unsafe/outside registered architecture'),
  ('accepted', 'routed', 'workflow and role targets resolve'),
  ('routed', 'tasks_created', 'command and tasks committed atomically'),
  ('tasks_created', 'in_progress', 'child execution starts'),
  ('in_progress', 'partially_blocked', 'child blocker opens'),
  ('partially_blocked', 'in_progress', 'blocker resolved'),
  ('in_progress', 'completed', 'all closure criteria pass'),
  ('partially_blocked', 'completed', 'all blockers resolved and closure passes'),
  ('received', 'cancelled', 'founder cancels before routing'),
  ('accepted', 'cancelled', 'founder cancels before task creation'),
  ('routed', 'cancelled', 'safe cancellation before execution'),
  ('tasks_created', 'cancelled', 'task cancellation/compensation accepted'),
  ('in_progress', 'cancelled', 'workflow cancellation policy accepts'),
  ('received', 'failed', 'technical intake failure'),
