-- What makes an instruction actionable rather than a wish.  A command must carry at least one
-- of these, which is why "Make marketing better" asks a question and does not create work.
insert into public.phase_c_command_specificity_signal (signal_id, pattern, kind) values
  ('quantity',    '(^|[^a-z0-9])([0-9]+|one|two|three|five|ten|twenty|fifty|hundred)([^a-z0-9]|$)', 'quantity'),
  ('deadline',    '(today|tonight|tomorrow|this (week|month|quarter)|next (week|month|quarter)|by (monday|tuesday|wednesday|thursday|friday|saturday|sunday)|deadline|due|now|immediately|[0-9]+[- ]day)', 'deadline'),
  ('identifier',  '(\m(TX|CMD|TASK|RFQ|INV|SUP|W[0-9]{2})[- ]?[A-Za-z0-9]+\M|#[0-9]+|\msupplier [0-9]+\M)', 'identifier'),
  ('deliverable', '(post|article|report|forecast|review|audit|gate|release|deploy|campaign|department|page|error|bug|experience|agreement|contract|policy|fee|price|percent|target|suppliers?|customers?|refund)', 'deliverable'),
  ('geography',   '(dubai|abu dhabi|sharjah|uae|saudi|qatar|oman|kuwait|bahrain|gcc)', 'geography'),
  ('named_scope', '(arabic|english|mobile|desktop|signup|registration|privacy|security|quality|cash|social media)', 'named_scope')
on conflict (signal_id) do update set pattern = excluded.pattern, kind = excluded.kind;

-- The deterministic command registry.  Ordered; first match wins; rule_order is unique so a tie
-- is impossible.  This table IS the router — reading it tells you exactly what any sentence will
-- do, and no model is consulted at any point.
insert into public.phase_c_command_rule
  (rule_id, rule_order, pattern, antipattern, intent_id, outcome, workflow_ids,
   primary_role_id, child_role_ids, requires_specificity, priority, notes) values
  ('CR-010', 10, '(refund|pay|credit|delete|remove|ban|suspend|cancel).{0,30}\m(every|all)\M.{0,30}(customer|supplier|user|account|order|transaction)|\m(every|all)\M (customer|supplier|user|account)s?.{0,30}(refund|paid|deleted|banned)', '', 'CMD-W17', 'REFUSE_UNSCOPED_UNSAFE_COMMAND', 'W17', 'chief_of_staff', '', false, 'P0', 'CC-017: blanket destructive or financial instruction. Refused before routing, not after.'),
  ('CR-020', 20, '^\s*(what is |what.s )?(the )?status\M|\mstatus of\M', '', 'CMD-STATUS', 'QUERY_ONLY', '', 'chief_of_staff', '', true, 'P2', 'CC-012'),
  ('CR-021', 21, '^\s*cancel\M', '', 'CMD-CANCEL', 'CONTROL_COMMAND', '', 'chief_of_staff', '', true, 'P0', 'CC-013'),
  ('CR-022', 22, '\m(reprioriti[sz]e|make (it|this) (p[0-3]|urgent|top priority)|raise the priority|lower the priority)\M', '', 'CMD-REPRIORITIZE', 'CONTROL_COMMAND', '', 'chief_of_staff', '', true, 'P0', 'registry CMD-REPRIORITIZE'),
  ('CR-023', 23, '^\s*(explain|why did|why was|on what basis)\M', '', 'CMD-EXPLAIN', 'CONTROL_COMMAND', '', 'chief_of_staff', '', true, 'P2', 'registry CMD-EXPLAIN'),
  ('CR-030', 30, '\m(approve|reject|decline)\M.{0,40}\mrefund\M|\mrefund\M.{0,40}\m(TX-[A-Za-z0-9_-]+)', '', 'CMD-W17', 'REFUND_APPROVAL', 'W17', 'founder', 'payments_billing_manager; financial_controller', true, 'P1', 'CC-009 and CC-010'),
  ('CR-040', 40, '\m(reveal fee|subscription (price|fee)|commission (policy|rate)|pricing policy)\M', '', 'CMD-W01', 'FOUNDER_INITIATED_POLICY_CHANGE', 'W01;W27;W28', 'ceo', 'cfo; general_counsel; chief_revenue_officer', true, 'P1', 'CC-011: founder-initiated commercial policy change'),
  ('CR-041', 41, '\m(create|add|split|merge|remove|abolish)\M.{0,40}\m(department|division)\M', '', 'CMD-W30', 'FOUNDER_INITIATED_PHASE_A_CHANGE', 'W30', 'organisation_design_lead', 'coo; ceo', true, 'P1', 'CC-019: a Phase A structural change needs a formal change request, never an immediate mutation'),
  ('CR-042', 42, '^\s*research\M|\m(should we|whether we should|evaluate whether)\M', '', 'CMD-W01', 'RESEARCH_ONLY_UNTIL_FOUNDER_COMMAND', 'W01;W21;W28', 'strategy_director', 'market_intelligence_analyst; general_counsel; cfo', true, 'P2', 'CC-020: research is autonomous; commitment is not'),
  ('CR-050', 50, '\mand\M.{0,80}\m(make sure|ensure|also)\M|\m(campaign|launch)\M.{0,80}\msuppliers?\M', '', 'CMD-MULTI', 'MULTI_DEPARTMENT_PLAN', 'W03;W11;W20', 'chief_of_staff', 'chief_revenue_officer; supplier_coverage_liquidity_specialist; marketing_director', true, 'P1', 'CC-015'),
  ('CR-051', 51, '\minvestigate\M.{0,60}\msupplier\M|\msupplier response rate\M', '', 'CMD-W02', 'MULTI_DEPARTMENT_PLAN', 'W02;W19', 'corporate_performance_director', 'marketplace_director; supplier_retention_specialist; supplier_intelligence_analyst', true, 'P1', 'CC-003'),
  ('CR-060', 60, '\mban\M.{0,40}\msupplier\M|\msuspend\M.{0,40}\msupplier\M|\mfraud\M', '', 'CMD-W17', 'ROUTE_TO_INTERNAL_REVIEW', 'W17;W10', 'trust_safety_manager', 'fraud_reviewer; supplier_verification_reviewer', true, 'P1', 'CC-016: a raw command cannot ban an account; it opens an evidence review'),
  ('CR-061', 61, '\m(deploy|release|ship)\M|\m(security and quality|quality and security) gate\M|\mrelease gate\M', '', 'CMD-W24', 'ROUTE_TO_RELEASE_GATE', 'W24;W29', 'qa_release_management_director', 'cybersecurity_engineer; test_automation_engineer; it_operations_site_reliability_engineer', true, 'P1', 'CC-007 and CC-018: a raw command cannot bypass QA'),
  ('CR-062', 62, '\m(fix|bug|error|broken|improve|redesign)\M.{0,60}\m(page|signup|registration|experience|screen|form|flow|app|site)\M|\m(page|signup|registration)\M.{0,30}\m(error|bug|broken)\M', '', 'CMD-W22', 'ROUTE_AND_CREATE_TASKS', 'W22;W24', 'product_manager', 'product_ux_designer; engineering_manager; frontend_engineer; test_automation_engineer; qa_release_management_director', true, 'P1', 'CC-004 and CC-008'),
